text.main.ts:
// tilemap set up
tiles.setCurrentTilemap(assets.tilemap`tilemap`)
scene.setBackgroundColor(13)

// sprite set up
let squirrel = sprites.create(assets.image`squirrelSprite`, SpriteKind.Player)
tiles.placeOnTile(squirrel, tiles.getTileLocation(14, 1))
controller.moveSprite(squirrel)
scene.cameraFollowSprite(null)

let snake = sprites.create(assets.image`snakeSprite`, SpriteKind.Enemy)
tiles.placeOnRandomTile(snake, img`enemyTile`)

let acorn = sprites.create(assets.image`acornSprite`, SpriteKind.Food)
tiles.placeOnRandomTile(acorn, assets.tile`enemyTile`)

